#pragma once
/* isim simd for C and Objective-C (issue #800; generated by tools/simd-headers.py): Apple's <simd/common.h, geometry.h, logic.h, math.h and conversion.h> names over clang vector extensions,
 * header-only like Apple's. The functions are overloadable static inlines; Swift uses its own simd module, so they are
 * hidden from Swift (the types are not). */

