static inline __attribute__((__overloadable__, __always_inline__, __nodebug__)) simd_char1 simd_min(simd_char1 x, simd_char1 y) { return x < y ? x : y; }
static inline __attribute__((__overloadable__, __always_inline__, __nodebug__)) simd_char1 simd_max(simd_char1 x, simd_char1 y) { return x > y ? x : y; }
static inline __attribute__((__overloadable__, __always_inline__, __nodebug__)) simd_char1 simd_clamp(simd_char1 x, simd_char1 lo, simd_char1 hi) { return simd_min(simd_max(x, lo), hi); }
static inline __attribute__((__overloadable__, __always_inline__, __nodebug__)) simd_char1 simd_abs(simd_char1 x) { return x < 0 ? -x : x; }

